export function ChatAssistant() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([
    {
      sender: "bot",
      text: "Hello! I'm Anjum's Portfolio Assistant. How can I help you?",
      time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    },
  ]);

  const quickPrompts = [
    "What technologies do you work with?",
    "Tell me about your recent projects",
    "How can I contact you for work?",
  ];

  const sendQuestion = (value) => {
    const trimmed = (value ?? input).trim();
    if (!trimmed) return;

    const query = trimmed.toLowerCase();
    const match = assistantAnswers.find(({ keywords }) =>
      keywords.some((keyword) => query.includes(keyword))
    ) || {
      answer: "I can answer questions about Anjum's education, projects, skills, experience, and contact details. Try asking about her internships, work, or GitHub.",
    };

    setMessages((prev) => [
      ...prev,
      { sender: "user", text: trimmed },
      { sender: "bot", text: match.answer },
    ]);
    setInput("");
  };

  return (
    <div className="fixed bottom-5 right-5 z-50">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="flex h-14 w-14 items-center justify-center rounded-full border border-zinc-700 bg-[#f3f3f3] text-zinc-900 shadow-lg shadow-black/30 transition hover:scale-[1.02]"
          aria-label="Open chat assistant"
        >
          <MessageSquareText size={22} />
        </button>
      ) : (
        <div className="relative w-[420px] max-w-[92vw] overflow-hidden rounded-[18px] border border-zinc-800 bg-[#111214]/95 shadow-[0_20px_42px_rgba(0,0,0,0.7)] backdrop-blur-md">
          <div className="border-b border-zinc-800 bg-[#17181b] px-3 py-2.5">
            <div className="flex items-center gap-3">
              <img
                src={PROFILE_SRC}
                alt="Pathan Anjum Azra"
                className="h-9 w-9 rounded-full border border-zinc-700 object-cover"
              />
              <div className="min-w-0">
                <div className="text-[13px] font-semibold text-zinc-100 truncate">Pathan Anjum Azra's Portfolio Assistant</div>
                <div className="mt-0.5 flex items-center gap-1.5 text-[10px] text-zinc-300">
                  <span className="inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-emerald-400" />
                  <span>Online</span>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-2.5 bg-[#0d0d0f] px-3 py-3">
            <div className="flex items-start gap-2.5">
              <div className="mt-0.5 flex h-7 w-7 items-center justify-center rounded-full bg-gradient-to-br from-violet-500 to-pink-500 text-white shadow-lg shadow-violet-900/30">
                <MessageSquareText size={12} />
              </div>
              <div className="max-w-[85%] rounded-[16px] rounded-tl-md bg-zinc-800/80 px-3 py-2 text-[14px] leading-relaxed text-zinc-100 shadow-inner shadow-black/20">
                <div>Hello! I'm Anjum's Portfolio Assistant. How can I help you?</div>
                <div className="mt-1 text-[10px] text-zinc-500">{messages[0]?.time || "07:53 pm"}</div>
              </div>
            </div>

            <div className="space-y-2">
              <div className="text-[11px] text-zinc-400">Quick questions:</div>
              <div className="flex flex-wrap gap-1.5">
                {quickPrompts.map((prompt) => (
                  <button
                    key={prompt}
                    type="button"
                    onClick={() => sendQuestion(prompt)}
                    className="rounded-full border border-zinc-700 bg-zinc-900/80 px-2.5 py-1.5 text-left text-[12px] text-zinc-200 transition hover:border-violet-500 hover:bg-zinc-800 hover:text-white"
                  >
                    {prompt}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="h-[220px] overflow-y-auto bg-[#111214] p-2.5 space-y-2.5">
            {messages.slice(1).map((msg, idx) => (
              <div key={idx} className={`flex ${msg.sender === "user" ? "justify-end" : "justify-start"}`}>
                <div
                  className={`max-w-[85%] rounded-xl px-2.5 py-2 text-[13px] leading-relaxed ${
                    msg.sender === "user"
                      ? "bg-violet-600 text-white"
                      : "bg-zinc-800 text-zinc-200 border border-zinc-700"
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
          </div>

          <div className="flex items-center gap-2 border-t border-zinc-800 bg-[#111214] p-2.5">
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") sendQuestion();
              }}
              placeholder="Ask me about my work and experience..."
              className="flex-1 rounded-xl border border-zinc-700 bg-[#1a1b1f] px-2.5 py-2 text-[13px] text-zinc-100 placeholder:text-zinc-500 outline-none focus:border-violet-500"
            />
            <button
              onClick={() => sendQuestion()}
              className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f3f3f3] text-zinc-900 transition hover:bg-white"
              aria-label="Send message"
            >
              <ArrowUp size={16} />
            </button>
          </div>

          <button
            onClick={() => setIsOpen(false)}
            className="absolute -bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full border border-zinc-700 bg-[#f3f3f3] text-zinc-900 shadow-lg shadow-black/20"
            aria-label="Close chat assistant"
          >
            <span className="text-base">✕</span>
          </button>
        </div>
      )}
    </div>
  );
}

